// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		InternalEvent, Issue, Outbox, ScheduledTask, SessionBinding, Thread, Topic,
		TriggerMessage []ent.Hook
	}
	inters struct {
		InternalEvent, Issue, Outbox, ScheduledTask, SessionBinding, Thread, Topic,
		TriggerMessage []ent.Interceptor
	}
)
